begin;
create view public.engineering_revenue_budget_actual with(security_invoker=true) as with planned as(select m.tenant_id,m.company_id,c.work_id,m.competence,sum(fs.net_amount) planned_revenue from public.measurements m join public.engineering_contracts c on c.tenant_id=m.tenant_id and c.company_id=m.company_id and c.id=m.contract_id join public.measurement_financial_summary fs on fs.tenant_id=m.tenant_id and fs.company_id=m.company_id and fs.measurement_id=m.id where m.status in('closed','approved') group by m.tenant_id,m.company_id,c.work_id,m.competence),actual as(select fe.tenant_id,fe.company_id,fe.work_id,date_trunc('month',s.settled_on)::date competence,sum(s.amount) actual_revenue from public.financial_entries fe join public.financial_installments i on i.tenant_id=fe.tenant_id and i.company_id=fe.company_id and i.entry_id=fe.id join public.financial_settlements s on s.tenant_id=i.tenant_id and s.company_id=i.company_id and s.installment_id=i.id where fe.entry_type='income' and fe.measurement_id is not null group by fe.tenant_id,fe.company_id,fe.work_id,date_trunc('month',s.settled_on)::date),keys as(select tenant_id,company_id,work_id,competence from planned union select tenant_id,company_id,work_id,competence from actual) select k.tenant_id,k.company_id,k.work_id,w.name work_name,k.competence,coalesce(p.planned_revenue,0)::numeric(18,2) planned_revenue,coalesce(a.actual_revenue,0)::numeric(18,2) actual_revenue,(coalesce(p.planned_revenue,0)-coalesce(a.actual_revenue,0))::numeric(18,2) variance,case when coalesce(p.planned_revenue,0)>0 then round(coalesce(a.actual_revenue,0)*100/p.planned_revenue,2) else 0 end realization_percent from keys k join public.works w on w.tenant_id=k.tenant_id and w.company_id=k.company_id and w.id=k.work_id left join planned p on p.tenant_id=k.tenant_id and p.company_id=k.company_id and p.work_id=k.work_id and p.competence=k.competence left join actual a on a.tenant_id=k.tenant_id and a.company_id=k.company_id and a.work_id=k.work_id and a.competence=k.competence;
create view public.engineering_revenue_dashboard with(security_invoker=true) as select tenant_id,company_id,work_id,work_name,sum(planned_revenue)::numeric(18,2) planned_revenue,sum(actual_revenue)::numeric(18,2) actual_revenue,sum(variance)::numeric(18,2) variance,case when sum(planned_revenue)>0 then round(sum(actual_revenue)*100/sum(planned_revenue),2) else 0 end realization_percent from public.engineering_revenue_budget_actual group by tenant_id,company_id,work_id,work_name;
commit;